from typing import Optional, List
from itertools import permutations


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """Fill an n x n grid with 'A', 'B', 'C' so that each row and column is a
    permutation of the letters (Latin-square style), with the leftmost letter of
    row i equal to r[i] and the topmost letter of column j equal to c[j].
    Returns the grid as a list of strings, or None if impossible.
    """
    letters = 'ABC'
    if n == 3:
        # Latin squares of order 3 are all cyclic shifts of 'ABC' or 'ACB' rows
        pass  # general search below covers this

    rows = [''.join(p) for p in permutations(letters)]
    if n > 3:
        return None  # rows must be permutations of 3 letters for this interpretation

    cand = [row for row in rows if row[0] == r[0]]  # placeholder; general check below
    grid = [None] * n

    def search(i):
        if i == n:
            for j in range(n):
                col = ''.join(grid[k][j] for k in range(n))
                if sorted(col) != sorted(letters) or col[0] != c[j]:
                    return False
            return True
        for row in rows:
            if row[0] != r[i]:
                continue
            grid[i] = row
            if search(i + 1):
                return True
        grid[i] = None
        return False

    if search(0):
        return list(grid)
    return None

