from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]
    # row_has[i][ch] / col_has[j][ch]: whether letter ch already placed in row i / column j
    row_has = [set() for _ in range(n)]
    col_has = [set() for _ in range(n)]

    def first_char_ok_row(i):
        for ch in grid[i]:
            if ch != '.':
                return ch == r[i]
        return True  # not yet determined

    def first_char_ok_col(j):
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == c[j]
        return True

    def final_row_check(i):
        # the first placed char in row i must equal r[i]
        for ch in grid[i]:
            if ch != '.':
                return ch == r[i]
        return False

    def final_col_check(j):
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == c[j]
        return False

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(idx):
        if idx == len(cells):
            # verify every row/column has exactly one of each letter
            for i in range(n):
                if sorted(x for x in grid[i] if x != '.') != ['A', 'B', 'C']:
                    return False
                if not final_row_check(i):
                    return False
            for j in range(n):
                if sorted(grid[i][j] for i in range(n) if grid[i][j] != '.') != ['A', 'B', 'C']:
                    return False
                if not final_col_check(j):
                    return False
            return True

        i, j = cells[idx]
        # Option 1: leave the cell empty
        if backtrack(idx + 1):
            return True
        # Option 2: place a letter
        for ch in letters:
            if ch in row_has[i] or ch in col_has[j]:
                continue
            # Prune: if this is the first letter placed in row i, it must match r[i]
            if not row_has[i] and ch != r[i]:
                continue
            # Prune: if this is the first letter placed in column j, it must match c[j]
            if not col_has[j] and ch != c[j]:
                continue
            grid[i][j] = ch
            row_has[i].add(ch)
            col_has[j].add(ch)
            if backtrack(idx + 1):
                return True
            row_has[i].discard(ch)
            col_has[j].discard(ch)
            grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

