def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = ['A', 'B', 'C']
    # Each row/column has exactly 3 letters placed (A, B, C once each) and n-3 empty cells.
    # Enumerate per-row placements: choose a set of 3 positions and an assignment of A/B/C to them.
    from itertools import combinations, permutations

    row_options = []
    for pos in combinations(range(n), 3):
        for perm in permutations(letters):
            row = ['.'] * n
            for p, ch in zip(pos, perm):
                row[p] = ch
            # leftmost placed character is the one at the smallest position
            row_options.append(row)

    def leftmost(row):
        for ch in row:
            if ch != '.':
                return ch
        return None

    def topmost(col_idx, grid):
        for i in range(n):
            if grid[i][col_idx] != '.':
                return grid[i][col_idx]
        return None

    candidates = [row for row in row_options if leftmost(row) == r[0]] if False else None

    # Filter row options per row according to R
    per_row = []
    for i in range(n):
        per_row.append([row for row in row_options if leftmost(row) == r[i]])

    grid = [None] * n

    def search(i):
        if i == n:
            # Check every column has exactly one A, B, C and topmost matches C
            for j in range(n):
                col = [grid[k][j] for k in range(n) if grid[k][j] != '.']
                if sorted(col) != ['A', 'B', 'C']:
                    return None
                if topmost(j, grid) != c[j]:
                    return None
            return [''.join(row) for row in grid]
        for row in per_row[i]:
            grid[i] = row
            # Prune: column letters must not repeat so far
            ok = True
            for j in range(n):
                if row[j] != '.':
                    for k in range(i):
                        if grid[k][j] == row[j]:
                            ok = False
                            break
                if not ok:
                    break
            if ok:
                res = search(i + 1)
                if res is not None:
                    return res
        grid[i] = None
        return None

    return search(0)

