def brute(n, r, c):
    letters = 'ABC'
    cells = [(i, j) for i in range(n) for j in range(n)]
    options = ['.', 'A', 'B', 'C']
    from itertools import product
    for assign in product(options, repeat=n*n):
        g = [list(assign[i*n:(i+1)*n]) for i in range(n)]
        ok = True
        for i in range(n):
            row = [x for x in g[i] if x != '.']
            if sorted(row) != ['A','B','C']:
                ok = False; break
            if [x for x in g[i] if x != '.'][0] != r[i]:
                ok = False; break
        if not ok: continue
        for j in range(n):
            col = [g[i][j] for i in range(n) if g[i][j] != '.']
            if sorted(col) != ['A','B','C']:
                ok = False; break
            if [g[i][j] for i in range(n) if g[i][j] != '.'][0] != c[j]:
                ok = False; break
        if ok:
            return [''.join(row) for row in g]
    return None

