def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    # All valid row patterns: exactly one A, B, C, rest '.'
    row_patterns = []
    for pos in combinations(range(n), 3):
        for perm in permutations('ABC'):
            row = ['.'] * n
            for p, ch in zip(pos, perm):
                row[p] = ch
            row_patterns.append(tuple(row))

    def leftmost(row):
        for ch in row:
            if ch != '.':
                return ch
        return None

    # Restrict each row to patterns whose leftmost letter equals r[i]
    options = [
        [p for p in row_patterns if leftmost(p) == r[i]]
        for i in range(n)
    ]

    chosen = [None] * n

    def column_ok_partial(rows_done):
        # for each column, check letters so far don't repeat and topmost matches c[j]
        for j in range(n):
            seen = []
            for i in range(rows_done):
                if chosen[i][j] != '.':
                    seen.append(chosen[i][j])
            if len(seen) != len(set(seen)):
                return False
            if seen and seen[0] != c[j] and not any(
                    chosen[i][j] != '.' for i in range(0)):
                pass
        return True

    def search(i):
        if i == n:
            for j in range(n):
                col = [chosen[k][j] for k in range(n) if chosen[k][j] != '.']
                if sorted(col) != ['A', 'B', 'C']:
                    return None
                first = next(chosen[k][j] for k in range(n) if chosen[k][j] != '.')
                if first != c[j]:
                    return None
            return [''.join(row) for row in chosen]
        for p in options[i]:
            chosen[i] = p
            if column_ok_partial(i + 1):
                res = search(i + 1)
                if res is not None:
                    return res
        chosen[i] = None
        return None

    return search(0)

