def exists(n, r, c):
    for flat in product('.ABC', repeat=n*n):
        g = [flat[i*n:(i+1)*n] for i in range(n)]
        good = True
        for i in range(n):
            letters = [x for x in g[i] if x != '.']
            if sorted(letters) != ['A', 'B', 'C'] or letters[0] != r[i]:
                good = False; break
        if not good:
            continue
        for j in range(n):
            col = [g[i][j] for i in range(n) if g[i][j] != '.']
            if sorted(col) != ['A', 'B', 'C'] or col[0] != c[j]:
                good = False; break
        if good:
            return [''.join(row) for row in g]
    return None

