from typing import Optional, Tuple


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    # Each point is counted once per cube containing it: V1 + 2*V2 + 3*V3 = 3*343
    if V1 + 2 * V2 + 3 * V3 != 1029:
        return None

    def ov(p, q):
        return max(0, 7 - abs(p - q))

    rng = range(-7, 8)
    for a2 in rng:
        for a3 in rng:
            x12 = ov(0, a2)
            x13 = ov(0, a3)
            x23 = ov(a2, a3)
            xt = max(0, 7 - (max(0, a2, a3) - min(0, a2, a3)))
            for b2 in rng:
                for b3 in rng:
                    y12 = ov(0, b2)
                    y13 = ov(0, b3)
                    y23 = ov(b2, b3)
                    yt = max(0, 7 - (max(0, b2, b3) - min(0, b2, b3)))
                    for c2 in rng:
                        for c3 in rng:
                            z12 = ov(0, c2)
                            z13 = ov(0, c3)
                            z23 = ov(c2, c3)
                            zt = max(0, 7 - (max(0, c2, c3) - min(0, c2, c3)))
                            T = xt * yt * zt
                            P12 = x12 * y12 * z12
                            P13 = x13 * y13 * z13
                            P23 = x23 * y23 * z23
                            V2c = P12 + P13 + P23 - 3 * T
                            V1c = 1029 - 2 * V2c - 3 * T
                            if (V1c, V2c, T) == (V1, V2, V3):
                                return (0, 0, 0, a2, b2, c2, a3, b3, c3)
    return None

