from typing import Optional, Tuple
from itertools import product


def _inter_volume(cubes, idxs):
    vol = 1
    for k in range(3):
        lo = max(cubes[i][k] for i in idxs)
        hi = min(cubes[i][k] for i in idxs) + 7
        vol *= max(0, hi - lo)
    return vol


def _region_volumes(cubes):
    p12 = _inter_volume(cubes, (0, 1))
    p13 = _inter_volume(cubes, (0, 2))
    p23 = _inter_volume(cubes, (1, 2))
    t = _inter_volume(cubes, (0, 1, 2))
    V3 = t
    V2 = p12 + p13 + p23 - 3 * t
    V1 = 3 * 343 - 2 * V2 - 3 * V3
    return V1, V2, V3


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V1 + 2 * V2 + 3 * V3 != 1029:
        return None

    rng = range(-7, 8)
    for a2, b2, c2 in product(rng, repeat=3):
        for a3, b3, c3 in product(rng, repeat=3):
            cubes = ((0, 0, 0), (a2, b2, c2), (a3, b3, c3))
            if _region_volumes(cubes) == (V1, V2, V3):
                return (0, 0, 0, a2, b2, c2, a3, b3, c3)
    return None

