def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid_area = h * w
    total_area = sum(a * b for a, b in tiles)
    # Quick reject: the tiles we use must cover the grid exactly, and we can
    # only use a subset, so the sum of all tiles must be at least the grid area.
    if total_area < grid_area:
        return False

    filled = [[False] * w for _ in range(h)]
    used = [False] * len(tiles)

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not filled[r][c]:
                    return r, c
        return None

    def fits(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if filled[i][j]:
                    return False
        return True

    def set_cells(r, c, rh, rw, value):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                filled[i][j] = value

    def backtrack():
        pos = first_empty()
        if pos is None:
            return True
        r, c = pos
        tried = set()
        for idx, (a, b) in enumerate(tiles):
            if used[idx]:
                continue
            # Skip identical tile shapes already attempted at this position
            key = (min(a, b), max(a, b))
            if key in tried:
                continue
            orientations = {(a, b), (b, a)}
            placed_any = False
            for rh, rw in orientations:
                if fits(r, c, rh, rw):
                    tried.add(key)
                    used[idx] = True
                    set_cells(r, c, rh, rw, True)
                    if backtrack():
                        return True
                    set_cells(r, c, rh, rw, False)
                    used[idx] = False
                    placed_any = True
            if placed_any:
                continue
        return False

    return backtrack()

def brute_force_tiling(h, w, tiles):
    grid = [[None] * w for _ in range(h)]
    found = []

    def first_empty():
        for r in range(h):
            for c in range(w):
                if grid[r][c] is None:
                    return r, c
        return None

    def rec(remaining):
        pos = first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in remaining:
            a, b = tiles[idx]
            for rh, rw in {(a, b), (b, a)}:
                if r + rh > h or c + rw > w:
                    continue
                if any(grid[i][j] is not None
                       for i in range(r, r + rh) for j in range(c, c + rw)):
                    continue
                for i in range(r, r + rh):
                    for j in range(c, c + rw):
                        grid[i][j] = idx
                found.append((idx, r, c, rh, rw))
                if rec([k for k in remaining if k != idx]):
                    return True
                found.pop()
                for i in range(r, r + rh):
                    for j in range(c, c + rw):
                        grid[i][j] = None
        return False

    ok = rec(list(range(len(tiles))))
    return ok, found


