def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def is_black_cell(i: int, j: int) -> bool:
        # Unit cell [i, i+1] x [j, j+1]; color determined by the cell's
        # position relative to the lines x=n, y=even, x+y=even.
        # Parity of the cell's lower-left corner under the pattern rule.
        # Cell (0,0) contains (0.5, 0.5) and is black.
        # Crossing a vertical line flips color; crossing a horizontal
        # line at even y flips color; crossing a diagonal at even n flips.
        # Using the canonical form: black iff (i + floor(j/2)) is even
        # with the diagonal adjustment below.
        jj = j // 2 if j >= 0 else -((-j + 1) // 2)
        s = (i + jj) % 2
        return s == 0

