        # Full 2x2 blocks contribute 2 black cells each -> twice-area 4 per block.
        # Handle remaining partial rows/columns cell by cell.
        bx, by = (x // 2) * 2, (y // 2) * 2
        total += (bx // 2) * (by // 2) * 4 * 2  # 2 blocks worth, doubled
        # Remaining strips of width 1 (x) and height 1 (y).
        for i in range(bx, x):
            for j in range(0, by):
                if is_black_cell(i, j):
                    total += 2
        for j in range(by, y):
            for i in range(0, x):
                if is_black_cell(i, j):
                    total += 2
        return total

    def twice_black_prefix_signed(x: int, y: int) -> int:
        sx = -1 if x < 0 else 1
        sy = -1 if y < 0 else 1
        return sx * sy * twice_black_prefix(abs(x), abs(y))

    return (
        twice_black_prefix_signed(C, D)
        - twice_black_prefix_signed(A, D)
        - twice_black_prefix_signed(C, B)
        + twice_black_prefix_signed(A, B)
    )

