def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def lines_between(lo, hi, values):
        a, b = min(lo, hi), max(lo, hi)
        return sum(1 for v in values if a < v < b)

    def is_black(x, y):
        # Count dividing lines separating (x, y) from (0.5, 0.5).
        # Vertical: x = n, horizontal: y = 2k, diagonal: x + y = 2k.
        cnt = 0
        cnt += lines_between(Fraction(1, 2), x, range(-10**6, 10**6))
        cnt += lines_between(Fraction(1, 2), y, range(-10**6, 10**6, 2))
        cnt += lines_between(Fraction(1), x + y, range(-10**6, 10**6, 2))
        return cnt % 2 == 0

    # Brute force over unit cells, sampling each half-cell by its centroid.
    total = 0
    for i in range(A, C):
        for j in range(B, D):
            for (px, py) in [(Fraction(2 * i + 1, 3), Fraction(2 * j + 1, 3)),
                             (Fraction(2 * i + 2, 3), Fraction(2 * j + 2, 3))]:
                if is_black(px, py):
                    total += 1
    return total

