def find_palindrome_expression(n: int) -> str:
    """Find a palindrome string S over digits 1-9 and '*' that evaluates to n.

    Returns '-1' if no such string is found by the bounded search.
    """
    if n < 1:
        return '-1'

    def is_valid(expr):
        if not expr or expr != expr[::-1]:
            return False
        if not expr[0].isdigit():
            return False
        if not all(c in '123456789*' for c in expr):
            return False
        if len(expr) > 1000:
            return False
        try:
            return eval(expr) == n
        except Exception:
            return False

    if 1 <= n <= 9:
        return str(n)

    def palindromes_dividing(m, max_digits):
        found = []
        for length in range(1, max_digits + 1):
            half = (length + 1) // 2
            prefixes = ['']
            for _ in range(half):
                prefixes = [p + d for p in prefixes for d in '123456789']
            for p in prefixes:
                pal = p + p[::-1][1:] if length % 2 else p + p[::-1]
                v = int(pal)
                if v <= m and m % v == 0:
                    found.append(pal)
        return found

    divisors = palindromes_dividing(n, 12)

    for d in divisors:
        if int(d) == n and is_valid(d):
            return d

    for a in divisors:
        av = int(a)
        if n % (av * av) != 0:
            continue
        rem = n // (av * av)
        for b in divisors:
            if int(b) == rem:
                expr = f"{a}*{b}*{a}"
                if is_valid(expr):
                    return expr

    return '-1'

