def find_palindrome_expression(n: int) -> str:
    """Find a palindrome string S over digits 1-9 and '*' that evaluates to n.

    Returns '-1' if no such string is found.
    """
    if n <= 0:
        return '-1'

    # Single-digit case
    if 1 <= n <= 9:
        return str(n)

    # Build palindromic expressions as products of palindromic "factors".
    # A factor is a palindrome over digits 1-9 (no zeros allowed).
    # The full expression is a palindrome of factors joined by '*' that is
    # itself a palindrome: f1*f2*...*fk where the sequence of factors is
    # a palindrome (f_i == f_{k+1-i}), so the string reverses to itself.

    def palindromic_factors(limit_value, max_len):
        """Generate palindromic numbers using digits 1-9 that divide n."""
        results = []
        # Generate palindromes by length (odd and even), digits 1-9 only
        for length in range(1, max_len + 1):
            half = (length + 1) // 2
            # enumerate all digit strings for first half
            stack = ['']
            for _ in range(half):
                new_stack = []
                for s in stack:
                    for d in '123456789':
                        new_stack.append(s + d)
                stack = new_stack
                if len(stack) > 200000:
                    break
            for s in stack:
                if length % 2 == 0:
                    pal = s + s[::-1]
                else:
                    pal = s + s[-2::-1]
                val = int(pal)
                if val <= limit_value and limit_value % val == 0:
                    results.append(pal)
        return results

    def is_valid(expr):
        if not expr or expr != expr[::-1]:
            return False
        if not expr[0].isdigit():
            return False
        if not all(c in '123456789*' for c in expr):
            return False
        if len(expr) > 1000:
            return False
        try:
            return eval(expr) == n
        except Exception:
            return False

    # Try single palindromic factor first
    for pal in palindromic_factors(n, 12):
        if int(pal) == n and is_valid(pal):
            return pal

    # Try palindromic sequences of two or three factors whose product is n
    factors = palindromic_factors(n, 12)
    factor_vals = {}
