def sum_of_scores(n: int, m: int) -> int:
    primes = [2, 3, 5, 7, 11, 13]
    P = len(primes)

    def factor(v):
        e = []
        for p in primes:
            c = 0
            while v % p == 0:
                v //= p
                c += 1
            e.append(c)
        return tuple(e)

    vecs = [factor(v) for v in range(1, m + 1)]

    from collections import defaultdict
    cur = defaultdict(int)
    cur[tuple([0] * P)] = 1
    total = 0
    limit = min(n, 12)
    for _ in range(limit):
        nxt = defaultdict(int)
        for st, c in cur.items():
            for v in vecs:
                ns = tuple(a + b for a, b in zip(st, v))
                nxt[ns] = (nxt[ns] + c) % MOD
        cur = nxt
        for st, c in cur.items():
            d = 1
            for e in st:
                d *= e + 1
            total = (total + c * d) % MOD
    return total % MOD

