from itertools import permutations


def _lis(p):
    n = len(p)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if p[j] < p[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp) if dp else 0


def _lds(p):
    return _lis([-x for x in p])


def _extendable(p):
    # Condition 3: there is an n such that appending n + 0.5 leaves
    # both LIS and LDS unchanged. Since the values are 1..L, the
    # candidate cut points are n in 0..L (n + 0.5 lies between values).
    L = len(p)
    base_inc, base_dec = _lis(p), _lds(p)
    for n in range(L + 1):
        # Appending n+0.5 shifts values >= n+1 down conceptually; the
        # relevant comparison is whether the new element can extend a
        # subsequence. Compare directly with the appended value.
        q = [x if x <= n else x for x in p] + [n + 0.5]
        if _lis(q) == base_inc and _lds(q) == base_dec:
            return True
    return False


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Brute-force reference for small A, B only (exponential time)."""
    total = A * B - 1
    count = 0
    for p in permutations(range(1, total + 1)):
        p = list(p)
        if _lis(p) == A and _lds(p) == B and _extendable(p):
            count += 1
    return count % M

