def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0

    def iroot(x, k):
        # Largest integer r with r**k <= x, by integer bisection (no floats).
        lo, hi = 1, 1
        while (hi + 1) ** k <= x:
            hi = hi * 2 + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo

    def mobius(m):
        result, d = 1, 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                result = -result
            d += 1
        if m > 1:
            result = -result
        return result

    # Distinct perfect powers >= 2 in [1, n]:
    #   sum over k >= 2 of -mu(k) * (iroot(n, k) - 1)
    # Plus 1 for the value 1.
    total = 0
    for k in range(2, 64):
        if (1 << k) > n:
            break
        mu = mobius(k)
        if mu != 0:
            total -= mu * (iroot(n, k) - 1)
    return total + 1

