def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]

    # Each row/column may contain each letter at most once.
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def first_letter_in_row(i: int) -> Optional[str]:
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def first_letter_in_col(j: int) -> Optional[str]:
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def valid_final() -> bool:
        for i in range(n):
            if first_letter_in_row(i) != r[i]:
                return False
        for j in range(n):
            if first_letter_in_col(j) != c[j]:
                return False
        return True

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(idx: int) -> bool:
        if idx == len(cells):
            return valid_final()
        i, j = cells[idx]
        # Try leaving the cell empty, then each letter.
        options = ['.'] + list(letters)
        for ch in options:
            if ch != '.':
                if ch in row_used[i] or ch in col_used[j]:
                    continue
                # Prune: if this cell is the leftmost filled cell of row i,
                # it must match r[i]; similarly for column j.
                if first_letter_in_row_before(i, j) is None and ch != r[i]:
                    continue
                if first_letter_in_col_before(j, i) is None and ch != c[j]:
                    continue
                grid[i][j] = ch
                row_used[i].add(ch)
                col_used[j].add(ch)
                if backtrack(idx + 1):
                    return True
                row_used[i].discard(ch)
                col_used[j].discard(ch)
                grid[i][j] = '.'
            else:
                # Empty cell: prune if it is the last cell of a row/column
                # that has no filled cell yet and that row/column requires a letter.
                if j == n - 1 and first_letter_in_row_before(i, n) is None:
                    continue
                if i == n - 1 and first_letter_in_col_before(j, n) is None:
                    continue
                if backtrack(idx + 1):
                    return True
        return False

    def first_letter_in_row_before(i: int, j: int) -> Optional[str]:
        for k in range(j):
            if grid[i][k] != '.':
                return grid[i][k]
        return None

    def first_letter_in_col_before(j: int, i: int) -> Optional[str]:
        for k in range(i):
            if grid[k][j] != '.':
                return grid[k][j]
        return None

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

