        col = [grid[k][j] for k in range(n)]
        for line, target in ((row, r[i]), (col, c[j])):
            filled = [ch for ch in line if ch != '.']
            if len(filled) != len(set(filled)):
                return False
            if filled and first_non_empty(line) != target:
                return False
        return True

    def complete_ok() -> bool:
        for i in range(n):
            row = grid[i]
            if sorted(ch for ch in row if ch != '.') != sorted(letters):
                return False
            if first_non_empty(row) != r[i]:
                return False
        for j in range(n):
            col = [grid[k][j] for k in range(n)]
            if sorted(ch for ch in col if ch != '.') != sorted(letters):
                return False
            if first_non_empty(col) != c[j]:
                return False
        return True

    def backtrack(idx: int) -> bool:
        if idx == len(cells):
            return complete_ok()
        i, j = cells[idx]
        for ch in ['.'] + list(letters):
            grid[i][j] = ch
            if partial_ok(i, j) and backtrack(idx + 1):
                return True
        grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

