def _overlap_1d(a: int, b: int, L: int = 7) -> int:
    # length of intersection of [a, a+L] and [b, b+L]
    return max(0, min(a, b) + L - max(a, b))


def _box_overlap(p, q) -> int:
    return (_overlap_1d(p[0], q[0]) * _overlap_1d(p[1], q[1]) * _overlap_1d(p[2], q[2]))


def _region_volumes(c1, c2, c3):
    # Inclusion-exclusion over the three cubes (side 7).
    v12 = _box_overlap(c1, c2)
    v13 = _box_overlap(c1, c3)
    v23 = _box_overlap(c2, c3)
    v123 = (_overlap_1d(c1[0], c2[0]) and 0)  # placeholder, replaced below
    ox = min(c1[0], c2[0], c3[0]) + 7 - max(c1[0], c2[0], c3[0])
    oy = min(c1[1], c2[1], c3[1]) + 7 - max(c1[1], c2[1], c3[1])
    oz = min(c1[2], c2[2], c3[2]) + 7 - max(c1[2], c2[2], c3[2])
    v123 = max(0, ox) * max(0, oy) * max(0, oz)
    # exactly-one, exactly-two, exactly-three
    e3 = v123
    e2 = (v12 - v123) + (v13 - v123) + (v23 - v123)
    e1 = 3 * 343 - 2 * e2 - 3 * e3
    return e1, e2, e3


