def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[False] * w for _ in range(h)]
    used = [False] * n
    total_area_needed = h * w

    # Precompute orientations for each tile (deduplicated)
    orients = []
    for a, b in tiles:
        s = {(a, b), (b, a)}
        orients.append(sorted(s))

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_cells(r, c, rh, rw, val):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = val

    def backtrack(remaining_area):
        if remaining_area == 0:
            return True
        pos = find_first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in range(n):
            if used[idx]:
                continue
            for rh, rw in orients[idx]:
                if can_place(r, c, rh, rw):
                    set_cells(r, c, rh, rw, True)
                    used[idx] = True
                    if backtrack(remaining_area - rh * rw):
                        return True
                    used[idx] = False
                    set_cells(r, c, rh, rw, False)
        return False

    return backtrack(total_area_needed)

