        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[False] * w for _ in range(h)]
    used = [False] * n

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def fits(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_block(r, c, rh, rw, val):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = val

    def solve():
        pos = first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in range(n):
            if used[idx]:
                continue
            a, b = tiles[idx]
            for rh, rw in {(a, b), (b, a)}:
                if fits(r, c, rh, rw):
                    set_block(r, c, rh, rw, True)
                    used[idx] = True
                    if solve():
                        return True
                    used[idx] = False
                    set_block(r, c, rh, rw, False)
        return False

    return solve()

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def is_black_point2(x2, y2):
        # Coordinates doubled (x2 = 2x, y2 = 2y), sample at centers of half-unit cells.
        # Point is black iff the number of separating lines crossed from (0.5,0.5) is even.
        # Lines crossed going from (0.5,0.5) to (x,y): vertical lines x=n and
        # diagonal lines x+y=2k (k integer) crossed, counted by parity.
        # Use floor functions on the true coordinates.
        import math
        x = x2 / 2.0
        y = y2 / 2.0
        # Count vertical lines x=n between 0.5 and x (exclusive)
        def vcount(a, b):
            lo, hi = min(a, b), max(a, b)
            return math.floor(hi) - math.floor(lo)
        # Count diagonal lines x+y=2k between s0=1 and s=x+y
        def dcount(a, b):
            lo, hi = min(a, b), max(a, b)
            # number of even integers e with lo < e < hi (or equal handled by generic points)
            return math.floor(hi / 2.0) - math.floor(lo / 2.0)
        n = vcount(0.5, x) + dcount(1.0, x + y)
        return n % 2 == 0

    # Sum over unit cells [i,i+1]x[j,j+1] by sampling sub-cells on a half-grid: each unit cell
    # is cut by at most one diagonal, so its black area is either 1/2 or 1 or 0 (exact).
    total = 0
    for i in range(A, C):
        for j in range(B, D):
            # Sample the four quarter-points of the unit cell; black area estimated exactly
            # by the number of black sample points times 1/4 of area 1 -> doubled gives
            # the count of black samples times 2 / 4 * 2 = count.
            cnt = 0
            for dx in (0.25, 0.75):
                for dy in (0.25, 0.75):
                    if is_black_point2(int(2 * (i + dx)), int(2 * (j + dy))):
                        cnt += 1
            total += cnt
    return total

