def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def is_black(x2, y2):
        # Sample point (x2/2, y2/2), with x2, y2 odd so it avoids all lines.
        # Count separating lines between (0.5, 0.5) and the sample point.
        # Lines: x = n, y = 2k, x + y = 2k.
        import math
        x = Fraction(x2, 2)
        y = Fraction(y2, 2)
        base_x, base_y = Fraction(1, 2), Fraction(1, 2)
        def count_int_between(a, b):
            lo, hi = min(a, b), max(a, b)
            return math.floor(hi) - math.floor(lo)
        def count_even_between(a, b):
            lo, hi = min(a, b), max(a, b)
            return math.floor(hi / 2) - math.floor(lo / 2)
        n = count_int_between(base_x, x) + count_even_between(base_y, y) + count_even_between(base_x + base_y, x + y)
        return n % 2 == 0

    total = 0
    for i in range(A, C):
        for j in range(B, D):
            cnt = 0
            for dx2 in (1, 3):
                for dy2 in (1, 3):
                    if is_black(2 * i + dx2, 2 * j + dy2):
                        cnt += 1
            total += cnt
    return total

