def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1

    # Hook length formula: number of SYT of shape lam (list of row lengths), mod M
    def syt_count(lam):
        n = sum(lam)
        if n == 0:
            return 1
        conj = [sum(1 for r in lam if r > j) for j in range(lam[0])]
        num = 1
        for i, r in enumerate(lam):
            for j in range(r):
                hook = (r - j - 1) + (conj[j] - i - 1) + 1
                num = num * hook % M
        # f = n! / prod(hooks); compute n! and inverse of hook product mod prime M
        fact = 1
        for k in range(2, n + 1):
            fact = fact * k % M
        return fact * pow(num, M - 2, M) % M

    total = 0
    # Candidate shapes: partitions of N with first row A and first column B,
    # i.e. hooks of size A + B - 1 inside an (A x B)-bounded region.
    # Shape must have lam[0] == A and len(lam) == B, with |lam| = AB - 1.
    # Enumerate rows 2..B: each row length in [1, A], non-increasing.
    def gen(rows_left, max_part, remaining, acc):
        if rows_left == 0:
            if remaining == 0:
                yield list(acc)
            return
        for part in range(min(max_part, remaining), 0, -1):
            if part * 1 > remaining:
                continue
            acc.append(part)
            yield from gen(rows_left - 1, part, remaining - part, acc)
            acc.pop()

    for lam_rest in gen(B - 1, A, N - A, []):
        lam = [A] + lam_rest
        f = syt_count(lam)
        total = (total + f * f) % M

    return total % M

