def count_special_permutations(A: int, B: int, M: int) -> int:
    from math import factorial

    N = A * B - 1

    def hook_count(shape):
        n = sum(shape)
        if n == 0:
            return 1
        conj = [sum(1 for r in shape if r > j) for j in range(shape[0])]
        prod = 1
        for i, r in enumerate(shape):
            for j in range(r):
                prod *= (r - j - 1) + (conj[j] - i - 1) + 1
        return factorial(n) // prod

    total = 0
    # Shapes: partitions of N inside an A x B box with lambda_1 = A and lambda'_1 = B
    def partitions(n, max_part, max_len):
        if n == 0:
            yield []
            return
        if max_len == 0:
            return
        for p in range(min(n, max_part), 0, -1):
            for rest in partitions(n - p, p, max_len - 1):
                yield [p] + rest

    for lam in partitions(N, A, B):
        if not lam or lam[0] != A or len(lam) != B:
            continue
        f = hook_count(lam)
        total += f * f

    return total % M

