def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """ Count the number of powerful integers in the range [start, finish].

    A positive integer x is called powerful if:
    1. It ends with s (s is a suffix of x)
    2. Each digit in x is at most limit
    """
    if any(int(c) > limit for c in s):
        return 0

    suffix_val = int(s)
    mod = 10 ** len(s)

    if finish < suffix_val:
        return 0

    hi = (finish - suffix_val) // mod
    if start <= suffix_val:
        lo = 0
    else:
        lo = -((-(start - suffix_val)) // mod)

    if lo > hi:
        return 0

    def count_upto(n: int) -> int:
        if n < 0:
            return 0
        if n == 0:
            return 1
        digits = list(map(int, str(n)))
        L = len(digits)
        base = limit + 1

        total = 1
        for m in range(1, L):
            total += limit * base ** (m - 1)
        for i, d in enumerate(digits):
            lo_digit = 1 if i == 0 else 0
            smaller = sum(1 for c in range(lo_digit, d) if c <= limit)
            total += smaller * base ** (L - i - 1)
            if d > limit:
                return total
        return total + 1

    return count_upto(hi) - count_upto(lo - 1)

