def count_power_representations(n: int) -> int:
    if n < 1:
        return 0

    def mobius(k: int) -> int:
        result, m, p = 1, k, 2
        while p * p <= m:
            if m % p == 0:
                m //= p
                if m % p == 0:
                    return 0
                result = -result
            p += 1
        if m > 1:
            result = -result
        return result

    def iroot(x: int, k: int) -> int:
        if x < 2:
            return x
        lo, hi = 1, 1
        while hi ** k <= x:
            hi *= 2
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo

